def main():
    OUT.mkdir(parents=True,exist_ok=True)
    summaries=[]
    for order,(title,description,minutes,blocks) in enumerate(LESSONS,1):
        # Every ordinary lesson states measurement conventions, not hidden prerequisites.
        if order<9:
            blocks=[blocks[0],t('Условия измерений',COMMON),*blocks[1:]]
        lesson=dict(id=f'body_electronics_{order:02}',moduleId='stage_11',order=order,title=title,
                    description=description,estimatedMinutes=minutes,
                    completion=dict(type='quiz',passingScore=80) if order==10 else dict(type='lesson'),blocks=blocks)
        file=f'lesson_{order:02}.json'
        (OUT/file).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        summaries.append({k:lesson[k] for k in ['id','order','title','description','estimatedMinutes']}|dict(file=file))
    (OUT/'lessons.json').write_text(json.dumps(summaries,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    scored={'question','calculation','voltageDrop','oscilloscope'}
    print('stage_11:',sum(len(x[3])+(x[0]!=LESSONS[-1][0] and i<8) for i,x in enumerate(LESSONS)),'blocks;',
          sum(b['type'] in scored for x in LESSONS for b in x[3]),'tasks')


if __name__=='__main__': main()
